{
  "passageId": "gongsun-long-later-mohists",
  "items": [
    {
      "id": "R1",
      "type": "DEVELOPMENT",
      "otherName": "",
      "reason": "정치·윤리 차원에 머물던 명실 논의가 독립적인 철학 영역으로 발전하는 시대적 전환이므로 3번에 해당한다."
    },
    {
      "id": "R2",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "명실 논쟁이라는 개괄적 설명을 논쟁 당사자인 공손룡의 구체적인 입장으로 풀어 주므로 7번에 해당한다."
    },
    {
      "id": "R3",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "명실 논쟁이라는 개괄적 설명을 후기 묵가의 구체적인 입장으로 풀어 주므로 7번에 해당한다."
    },
    {
      "id": "R4",
      "type": "PROCESS",
      "otherName": "",
      "reason": "미분화된 물에서 개별적인 실이 분화되어 나오는 선후 단계를 연결하므로 13번의 과정 관계에 해당한다."
    },
    {
      "id": "R5",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "실을 지시한다는 명의 역할을 차이의 구별·확정과 의사소통이라는 세부 기능으로 풀어 주므로 7번에 해당한다."
    },
    {
      "id": "R6",
      "type": "CAUSE",
      "otherName": "",
      "reason": "같은 명 때문에 실의 구별이 사라지고 그 결과 사람들 사이에 지시 대상의 혼란이 발생하는 작용을 설명하므로 10번에 해당한다."
    },
    {
      "id": "R7",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "동일한 명의 사용이 혼란을 낳는다는 설명이 일대일 대응을 지켜야 한다는 당위의 이유이므로 문제·대응이 아니라 9번에 해당한다."
    },
    {
      "id": "R8",
      "type": "MEANS_END",
      "otherName": "",
      "reason": "명의 사용에서 오해와 문제를 막으려는 목적을 위해 일대일 대응을 요구하므로 12번에 해당한다."
    },
    {
      "id": "R9",
      "type": "APPLICATION",
      "otherName": "",
      "reason": "명의 일대일 대응이라는 일반 원칙을 ‘말’과 ‘흰 말’의 구체적인 용법 문제에 가져다 쓰므로 6번에 해당한다."
    },
    {
      "id": "R10",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "형체를 가리키는 말과 색 속성이 결합한 흰 말의 차이를 백마 비마 주장의 근거로 제시하므로 9번에 해당한다."
    },
    {
      "id": "R11",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "흰 말에는 흰색 속성이 함께한다는 사실에서 말과 흰 말이 다르다는 판단을 도출하므로 9번에 해당한다."
    },
    {
      "id": "R12",
      "type": "CONTRAST",
      "otherName": "",
      "reason": "노란 말이나 검은 말을 가져올 수 있는지를 기준으로 말을 구하는 경우와 흰 말을 구하는 경우를 대비하므로 14번에 해당한다."
    },
    {
      "id": "R13",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "말과 흰 말을 구할 때 허용되는 대상의 차이가 백마 비마 주장을 뒷받침하므로 9번에 해당한다."
    },
    {
      "id": "R14",
      "type": "CRITIQUE",
      "otherName": "",
      "reason": "공손룡이 흰 말을 ‘말’로 지시하는 일상적 용법을 문제 삼고 두 명의 구분을 요구하므로 통념에 대한 비판에 해당한다."
    },
    {
      "id": "R15",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "두 명이 지시하는 실이 다르다는 판단을 이유로 용법을 구분해야 한다는 주장을 세우므로 9번에 해당한다."
    },
    {
      "id": "R16",
      "type": "CRITIQUE",
      "otherName": "",
      "reason": "후기 묵가가 흰 말도 말이라고 주장하며 공손룡의 백마 비마 주장을 명시적으로 반박하므로 1번의 비판 관계이다."
    },
    {
      "id": "R17",
      "type": "CRITIQUE",
      "otherName": "",
      "reason": "후기 묵가의 복수 명 허용은 공손룡의 엄격한 일대일 대응 원칙을 부정하는 논의로 제시되므로 단순한 견해 차이가 아니라 비판이다."
    },
    {
      "id": "R18",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "흰 말 하나를 ‘흰 말’과 ‘말’로 부르는 사례가 하나의 실에 여러 명이 대응한다는 설명을 구체화하므로 7번에 해당한다."
    },
    {
      "id": "R19",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "검은 말 하나를 ‘검은 말’과 ‘말’로 부르는 사례가 하나의 실에 여러 명이 대응한다는 설명을 구체화하므로 7번에 해당한다."
    },
    {
      "id": "R20",
      "type": "CRITIQUE",
      "otherName": "",
      "reason": "후기 묵가는 하나의 명이 하나의 실만 지시해야 한다는 공손룡의 주장을 명시적으로 부정하므로 1번의 비판 관계이다."
    },
    {
      "id": "R21",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "서로 다른 두 새를 모두 ‘학’이라 부르는 예가 하나의 명이 여러 사물을 지시한다는 설명을 구체화하므로 7번에 해당한다."
    },
    {
      "id": "R22",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "지시 범위에 따른 명의 분류와 상황적 용법에 관한 논의가 일대일 대응을 부정하는 입장의 이론적 근거를 설명하므로 9번에 해당한다."
    },
    {
      "id": "R23",
      "type": "DEFINITION",
      "otherName": "",
      "reason": "달명이 지시하는 대상의 뜻을 공손룡의 ‘물’, 곧 천지 만물에 대응시켜 풀어 주므로 견해의 일치가 아니라 8번의 뜻풀이 관계이다."
    },
    {
      "id": "R24",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "‘말’이라는 명을 속성을 공유하는 대상들을 지시하는 유명의 사례로 제시하므로 7번에 해당한다."
    },
    {
      "id": "R25",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "특정한 한 마리를 ‘새’로 부르는 경우가 유명을 단일 개체에 대응시켜 만드는 사명의 구체적 사례이므로 7번에 해당한다."
    },
    {
      "id": "R26",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "‘새’의 지시 대상 수에 따라 유명과 사명이 달라지는 사례가 명들의 외연 크기 차이를 구체적으로 보여 주므로 7번에 해당한다."
    },
    {
      "id": "R27",
      "type": "CRITIQUE",
      "otherName": "",
      "reason": "지문은 후기 묵가의 복수 대응론을 공손룡의 일대일 대응론에 대한 반대와 부정으로 제시하므로 단순한 관점 차이가 아니라 비판 관계이다."
    }
  ]
}

